"""Given types for the Gatekeeper lab. Do not edit this file.

These mirror the vocabulary of Chapter 2 of "Engineering Trust into LLM Pipelines".
"""
from __future__ import annotations

from enum import Enum

from pydantic import BaseModel, ConfigDict, Field, model_validator


class Predicate(str, Enum):
    ASSOCIATED_WITH = "associated_with"
    CAUSES = "causes"
    INHIBITS = "inhibits"
    ACTIVATES = "activates"
    UNRELATED_TO = "unrelated_to"
    UNCERTAIN = "uncertain"


# Predicates that assert a positive relationship.
ASSERTED = {
    Predicate.ASSOCIATED_WITH,
    Predicate.CAUSES,
    Predicate.INHIBITS,
    Predicate.ACTIVATES,
}


class ValueStatus(str, Enum):
    PRESENT = "present"
    NOT_FOUND_IN_SOURCE = "not_found_in_source"
    AMBIGUOUS = "ambiguous"
    NOT_APPLICABLE = "not_applicable"
    EXTRACTION_FAILED = "extraction_failed"
    WITHHELD = "withheld"


class Uncertainty(str, Enum):
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    UNKNOWN = "unknown"


class EvidenceSpan(BaseModel):
    """A claimed quotation from a normalized source text."""

    model_config = ConfigDict(extra="forbid")

    normalized_text_checksum: str = Field(pattern=r"^[a-f0-9]{64}$")
    quoted_text: str = Field(min_length=1)
    start_offset: int = Field(ge=0)
    end_offset: int = Field(gt=0)

    @model_validator(mode="after")
    def _offsets(self) -> "EvidenceSpan":
        if self.end_offset <= self.start_offset:
            raise ValueError("end_offset must be greater than start_offset")
        return self


class CheckStatus(str, Enum):
    PASSED = "passed"
    WARNING = "warning"
    FAILED = "failed"


class Finding(BaseModel):
    """One validator result. Validators produce findings; they never decide authority."""

    model_config = ConfigDict(extra="forbid")

    check_name: str
    status: CheckStatus
    issue_code: str | None = None
    detail: str | None = None


class Report(BaseModel):
    model_config = ConfigDict(extra="forbid")

    findings: list[Finding] = Field(default_factory=list)

    def has(self, issue_code: str) -> bool:
        return any(f.issue_code == issue_code for f in self.findings)


class ResolutionStatus(str, Enum):
    RESOLVED = "resolved"
    AMBIGUOUS = "ambiguous"
    NO_MATCH = "no_match"


class Candidate(BaseModel):
    model_config = ConfigDict(extra="forbid")

    identifier: str
    label: str


class ResolutionResult(BaseModel):
    model_config = ConfigDict(extra="forbid")

    entity_text: str
    status: ResolutionStatus
    normalized_id: str | None = None
    candidates: list[Candidate] = Field(default_factory=list)

    @model_validator(mode="after")
    def _consistent(self) -> "ResolutionResult":
        if self.status == ResolutionStatus.RESOLVED and self.normalized_id is None:
            raise ValueError("resolved requires normalized_id")
        if self.status != ResolutionStatus.RESOLVED and self.normalized_id is not None:
            raise ValueError("only a resolved result may carry normalized_id")
        if self.status == ResolutionStatus.AMBIGUOUS and len(self.candidates) < 2:
            raise ValueError("ambiguous requires at least two candidates")
        return self


class Consequence(str, Enum):
    LOW = "low"
    MODERATE = "moderate"
    HIGH = "high"
    CRITICAL = "critical"


class Assurance(str, Enum):
    BASIC = "basic"
    STANDARD = "standard"
    STRONG = "strong"
    HUMAN_CONFIRMED = "human_confirmed"


class Disposition(str, Enum):
    REJECT = "reject"
    QUARANTINE = "quarantine"
    HUMAN_REVIEW = "human_review"
    PROVISIONAL = "provisional"
    AUTHORITATIVE = "authoritative"


class Decision(BaseModel):
    model_config = ConfigDict(extra="forbid")

    disposition: Disposition
    reason_codes: list[str] = Field(default_factory=list)
